package com.dymbia.sumaqagro.platform.farming.domain.model.commands;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Command to record the wages of the field workers in a cost ledger.
 *
 * @param campaignLedgerId the ledger of the campaign
 * @param activity         the field work, such as "Siembra" or "Cosecha"
 * @param workers          the number of workers
 * @param days             the number of days worked
 * @param dailyWage        the wage of one worker for one day
 * @param expenseDate      the date of the payment
 * @param clientSyncId     the id generated by the device in offline mode, optional
 */
public record RecordDailyLaborExpenseCommand(Long campaignLedgerId, String activity, Integer workers, Integer days,
                                             BigDecimal dailyWage, LocalDate expenseDate, String clientSyncId) {
    public RecordDailyLaborExpenseCommand {
        if (campaignLedgerId == null || campaignLedgerId <= 0) {
            throw new IllegalArgumentException("campaign.ledger.error.id.invalid");
        }
        if (workers == null) {
            throw new IllegalArgumentException("expense.entry.error.labor.workers.invalid");
        }
        if (days == null) {
            throw new IllegalArgumentException("expense.entry.error.labor.days.invalid");
        }
    }
}